-- Copy to Sheets: triggers for post_comments (generated by setup/build-mirror-sql.mjs; see 0022 for the design).
CREATE TRIGGER mirror_post_comments_ins AFTER INSERT ON post_comments BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('post_comments', NEW."id", ''); END;
CREATE TRIGGER mirror_post_comments_upd AFTER UPDATE ON post_comments BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('post_comments', NEW."id", ''); END;
CREATE TRIGGER mirror_post_comments_key AFTER UPDATE ON post_comments WHEN OLD."id" IS NOT NEW."id" BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('post_comments', OLD."id", ''); END;
CREATE TRIGGER mirror_post_comments_del AFTER DELETE ON post_comments BEGIN INSERT INTO mirror_log (tbl, k1, k2) VALUES ('post_comments', OLD."id", ''); END;
INSERT OR IGNORE INTO mirror_state (tbl, mode) VALUES ('post_comments', 'build');
